```minizinc
include "globals.mzn";

% Input data
int: N = 20; % Number of steps to the solution
int: rows = 3;
int: cols = 3;
int: size = rows * cols;

array[1..rows, 1..cols] of int: puzzle_start = [
    | 0, 3, 6
    | 2, 4, 8
    | 1, 7, 5
];

array[1..rows, 1..cols] of int: puzzle_end = [
    | 1, 2, 3
    | 4, 5, 6
    | 7, 8, 0
];

% Flatten the puzzle states for easier indexing
array[1..size] of int: start_flat = [puzzle_start[r,c] | r in 1..rows, c in 1..cols];
array[1..size] of int: end_flat = [puzzle_end[r,c] | r in 1..rows, c in 1..cols];

% Decision variables:
% puzzle[t, pos] = tile at position pos (1..size) at step t (1..N+1)
array[1..N+1, 1..size] of var 0..8: puzzle;

% Helper function: position to row and column
function int: row_of(int: pos) = (pos - 1) div cols + 1;
function int: col_of(int: pos) = (pos - 1) mod cols + 1;

% Helper function: Manhattan distance between two positions
function int: manhattan(int: p1, int: p2) =
    abs(row_of(p1) - row_of(p2)) + abs(col_of(p1) - col_of(p2));

% Constraint: initial state
constraint forall(pos in 1..size) (
    puzzle[1, pos] = start_flat[pos]
);

% Constraint: final state at step N+1
constraint forall(pos in 1..size) (
    puzzle[N+1, pos] = end_flat[pos]
);

% Constraint: each step is a valid puzzle state (all tiles distinct)
constraint forall(t in 1..N+1) (
    alldifferent([puzzle[t, pos] | pos in 1..size])
);

% Constraint: moves between steps are valid sliding moves
% Exactly one tile moves into the empty space (0) position from adjacent position
constraint forall(t in 1..N) (
    let {
        var int: zero_pos_t;   % position of zero at step t
        var int: zero_pos_tp1; % position of zero at step t+1
    } in (
        % Find zero positions at step t and t+1
        zero_pos_t = arg_min([bool2int(puzzle[t, pos] = 0) * pos + (1 - bool2int(puzzle[t, pos] = 0)) * (size+1) | pos in 1..size]),
        zero_pos_tp1 = arg_min([bool2int(puzzle[t+1, pos] = 0) * pos + (1 - bool2int(puzzle[t+1, pos] = 0)) * (size+1) | pos in 1..size]),

        % zero moves to adjacent position (manhattan distance 1)
        manhattan(zero_pos_t, zero_pos_tp1) = 1 /\

        % For all positions except zero_pos_t and zero_pos_tp1, tiles remain the same
        forall(pos in 1..size where pos != zero_pos_t /\ pos != zero_pos_tp1) (
            puzzle[t, pos] = puzzle[t+1, pos]
        ) /\

        % The tile that moves into zero_pos_t at step t+1 is the tile that was at zero_pos_tp1 at step t
        puzzle[t+1, zero_pos_t] = puzzle[t, zero_pos_tp1]
    )
);

solve satisfy;

output [
    "{",
    "\"steps\": [",
    concat([
        "["
        ++ join(", ", [
            "[" ++ join(", ", [show(puzzle[t, (r-1)*cols + c]) | c in 1..cols]) ++ "]"
            | r in 1..rows
        ])
        ++ "]"
        | t in 1..N+1
    ]),
    "]",
    "}"
];
```

